ALIASES = {"Model X": "provider/model-x"}

def normalize(name: str) -> str:
    return name.lower()

files.test_adapter.py:
import unittest
from adapter import normalize

class AdapterTests(unittest.TestCase):
    def test_exact_alias(self):
        self.assertEqual(normalize("Model X"), "provider/model-x")

    def test_unknown_identifier(self):
        self.assertEqual(normalize("Custom-ID/Prod"), "Custom-ID/Prod")

    def test_similar_but_unknown(self):
        self.assertEqual(normalize("MODEL X"), "MODEL X")

if __name__ == "__main__":
    unittest.main()

